#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    long long maxGCDScore(std::vector<int>& nums, int k) {
        int n = nums.size();
        long long best = 0;
        for (int i = 0; i < n; ++i) {
            int curr_gcd = 0;
            for (int j = i; j < n; ++j) {
                curr_gcd = std::gcd(curr_gcd, nums[j]);
                long long len = j - i + 1;
                best = std::max(best, len * curr_gcd);

                int odd_count = 0;
                for (int m = i; m <= j; ++m) {
                    if ((nums[m] / curr_gcd) % 2 != 0) odd_count++;
                }
                if (odd_count <= k) {
                    best = std::max(best, len * (curr_gcd * 2LL));
                }
            }
        }
        return best;
    }
};

class Solution {
    public long maxGCDScore(int[] nums, int k) {
        int n = nums.length;
        long best = 0;
        for (int i = 0; i < n; i++) {
            int currGcd = 0;
            for (int j = i; j < n; j++) {
                currGcd = gcd(currGcd, nums[j]);
                long len = j - i + 1;
                best = Math.max(best, len * currGcd);

                int oddCount = 0;
                for (int m = i; m <= j; m++) {
                    if ((nums[m] / currGcd) % 2 != 0) oddCount++;
                }
                if (oddCount <= k) {
                    best = Math.max(best, len * (currGcd * 2L));
                }
            }
        }
        return best;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
}

