var maxGCDScore = function(nums, k) {
    const gcd = (a, b) => {
        while (b !== 0) {
            const t = b;
            b = a % b;
            a = t;
        }
        return a;
    };

    const n = nums.length;
    let best = 0;
    for (let i = 0; i < n; i++) {
        let currGcd = 0;
        for (let j = i; j < n; j++) {
            currGcd = gcd(currGcd, nums[j]);
            const len = j - i + 1;
            const baseScore = len * currGcd;
            if (baseScore > best) best = baseScore;

            let oddCount = 0;
            for (let m = i; m <= j; m++) {
                if (Math.floor(nums[m] / currGcd) % 2 !== 0) oddCount++;
            }
            if (oddCount <= k) {
                const upScore = len * currGcd * 2;
                if (upScore > best) best = upScore;
            }
        }
    }
    return best;
};
